items.explanation:
（1）算法的基本设计思想如下。
分别求出序列A 和B 的中位数，设为a 和b，求序列A 和B 的中位数过程如下：
1）若a=b，则a 或b 即为所求中位数，算法结束。
2）若a<b，则舍弃序列A 中较小的一半，同时舍弃序列B 中较大的一半,要求舍弃的长
度相等；
3）若a>b，则舍弃序列A 中较大的一半，同时舍弃序列B 中较小的一半，要求舍弃的

长度相等；
在保留的两个升序序列中，重复过程1）、2）、3），直到两个序列中只含一个元素时为
止，较小者即为所求的中位数。
（2）算法的实现如下：
int M_Search(int A[],int B[],int n){
int s1=0,d1=n-1,m1,s2=1,d2=n-1,m2;
//分别表示序列A 和B 的首位数、末位数和中位数
while(s1!=d1||s2!=d2){
m1=(s1+d1)/2;
m2=(s2+d2)/2;
if(A[m1]==B[m2])
return A[m1];   //满足条件1）
if(A[m1]<B[m2]){    //满足条件2)
if((s1+d1)%2==0) { //若元素个数为奇数
s1=m1;  //舍弃A 中间点以前的部分且保留中间点
d2=m2;  //舍弃B 中间点以后的部分且保留中间点
}
else{  //元素个数为偶数
s1=m1+1;  //舍弃A 中间点及中间点以前部分
d2=m2;
//舍弃B 中间点以后部分且保留中间点
}
}
else{    //满足条件3）
if((s1+d1)%2==0) { //若元素个数为奇数
d1=m1;  //舍弃A 中间点以后的部分且保留中间点
s2=m2;  //舍弃B 中间点以前的部分且保留中间点
}
else{  //元素个数为偶数
d1=m1+1;  //舍弃A 中间点以后部分且保留中间点
s2=m2;    //舍弃B 中间点及中间点以前部分
}
}
}
return A[s1]<B[s2]? A[s1]:B[s2];
}
（3）算法的时间复杂度为O(log2n)，空间复杂度为O(1)。

semaphore seets = 10, // 有10 个坐位的资源信号量
mutex = 1, // 取号机互斥信号量
haveCustom = 0; // 顾客与营业员同步，无顾客时营业员休息
process 顾客
{
P(seets); // 等空位
P(mutex); // 申请使用取号机
从取号机上取号;
V(mutex); // 取号完毕
V(haveCustom); // 通知营业员有新顾客到来
等待营业员叫号;
V(seets); // 离开坐位
    接受服务；
}
process 营业员
{
    while(True)
    {
P(haveCustom); // 没有顾客则休息
叫号;
为顾客服务;
    }
}
